// 只读页面逐候选调用原预览；办理、文书获知和正式继位均不由UI自行写账。
#include "political_succession_view.hpp"
#include "political_succession_nomination_detail.hpp"
#include <set>
namespace hanmo::resident {namespace {
using V=BoundaryValue;using A=V::Array;using D=V::Dict;using boundary::obj;
V identity(const WorldIdentity& s){StableId id;constexpr char hex[]="0123456789abcdef";for(auto b:s.world_id){id+=hex[b>>4];id+=hex[b&15];}return obj({{"world_id",V{id}},{"execution_epoch",V{s.execution_epoch}},{"revision",V{s.revision}},{"tick",V{s.tick}}});}
// 原实名来源不会以显示名称碰撞；UI只能提交这里的具名参数回原writer。
V action(const PoliticalSuccessionContext& x,const StableId& actor,const PoliticalSuccessionCommand& command,const StableId& label){auto q=preview_political_succession(x,actor,command);return obj({{"text",V{label}},{"command",V{political_succession_command_kind(command)}},{"params",encode_political_succession_command(command)},{"available",V{q.ok}},{"code",V{q.ok?StableId{}:q.error.original.code}}});}
// 只接受原Task已知索引提供的binding，再用同一原实交通知读复核；不扫描全局死亡账。
Outcome<std::optional<DeliveredTaskDeathNotice>> known_death(const PoliticalSuccessionViewContext& x,const StableId& actor,const StableId& predecessor){if(!x.known_notice_bindings||!x.business.sources.delivered_notice)return {false,{},common_failure("PoliticalSuccessionKnownNoticeReadRequired").error};auto keys=x.known_notice_bindings(actor);if(!keys.ok)return {false,{},keys.error};if(keys.value.size()>65536)return {false,{},common_failure("PoliticalSuccessionKnownNoticeLimit").error};std::set<StableId> seen;std::optional<DeliveredTaskDeathNotice> selected;const auto& common=x.business.sources.nominations.common;
 for(const auto& id:keys.value){if(!seen.insert(id).second)return {false,{},common_failure("PoliticalSuccessionKnownNoticeIndexMismatch",id).error};auto source=x.business.sources.delivered_notice(actor,id);if(!source.ok)return {false,{},source.error};if(!source.value||source.value->binding_fact_id!=id||source.value->recipient_actor_id!=actor||source.value->received_tick>common.tick())return {false,{},common_failure("PoliticalSuccessionKnownNoticeIndexMismatch",id).error};const auto& a=source.value->identity;const auto& b=common.state().identity;if(std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick))return {false,{},common_failure("PoliticalSuccessionKnownNoticeIdentityMismatch",id).error};if(source.value->decedent_actor_id==predecessor&&(!selected||source.value->received_tick<selected->received_tick))selected=std::move(source.value);}
 return {true,std::move(selected),{}};
}
}
BoundaryValue encode_political_succession_quote(const PoliticalSuccessionQuote& q){return obj({{"source_identity",identity(q.identity)},{"actor_id",V{q.actor_id}},{"duration",V{Integer{0}}},{"command_kind",V{political_succession_command_kind(q.command)}},{"params",encode_political_succession_command(q.command)},{"scope",V{"提名和本人接受仅记录意愿；正式就任只接原空缺首职，不继承私人资产或旧军令。"}}});}
Outcome<BoundaryValue> query_political_successions(const PoliticalSuccessionViewContext& view,const StableId& place,Integer cursor){const auto& x=view.business;const auto& n=x.sources.nominations;const auto& common=n.common;const auto actor=common.state().metadata.player_actor_id;auto here=politics_detail::place(common,actor);if(!here||here->place_id!=place)return {false,{},common_failure("PoliticalSuccessionLocalQueryRequired",place).error};if(cursor<0||cursor>std::numeric_limits<Integer>::max()-16)return {false,{},common_failure("PoliticalSuccessionCursorInvalid").error};auto available=politics_detail::available(common,n.activity,actor);if(!available.ok)return {false,{},available.error};auto valid=validate_political_successions(x);if(!valid.ok)return {false,{},valid.error};A rows;Integer count=0;
 // 只在分页命中后生成原预览；没有把远方人物列表或他人的意愿历史放入页面。
 auto append=[&](auto build){const auto at=count++;if(at>=cursor&&at<cursor+16)rows.push_back(build());};
 for(const auto& policy:n.catalog.policies.rows()){const auto& p=policy.second;if(p.seat_place_id!=place)continue;auto office=read_political_succession_office(common,n.organizations,n.organization_catalog,p);if(!office.ok)return {false,{},office.error};if(office.value.holder_actor_id!=std::optional<StableId>{actor}||office.value.original_leader_actor_id!=actor)continue;
  for(const auto& candidate:common.state().actors.rows()){if(candidate.first==actor)continue;auto at=politics_detail::place(common,candidate.first);if(!at||at->place_id!=place)continue;if(!succession_detail::contact(n,p,candidate.first).ok||!growth_independent_office_age(common,candidate.first).ok||!succession_detail::member_now(n,candidate.first,p.organization_id).ok)continue;
   append([&]{PoliticalNominateSuccessor command{{p.organization_id,p.leader_office_id,office.value.office_epoch,actor},p.id,candidate.first,office.value.office_epoch};return obj({{"kind",V{"nomination_option"}},{"policy_id",V{p.id}},{"candidate_actor_id",V{candidate.first}},{"actions",V{A{action(x,actor,command,"明确提名眼前本人")}}}});});
  }
 }
 for(const auto& entry:n.state.nominations.rows()){const auto& original=entry.second;const auto* p=n.catalog.policies.find(original.policy_id);if(!p||p->seat_place_id!=place||(original.issuer_actor_id!=actor&&original.candidate_actor_id!=actor))continue;const auto* accepted=succession_detail::accepted(n.state,original.id);const bool installed=succession_detail::acceded(n,original.id);
  std::optional<DeliveredTaskDeathNotice> notice;if(actor==original.candidate_actor_id&&accepted&&!installed&&count>=cursor&&count<cursor+16){auto known=known_death(view,actor,original.issuer_actor_id);if(!known.ok)return {false,{},known.error};notice=std::move(known.value);}
  append([&]{A answers,actions;for(const auto& answer:n.state.answers.rows())if(answer.second.nomination_fact_id==original.id&&(answer.second.accepted||answer.second.actor_id==actor))answers.push_back(obj({{"id",V{answer.first}},{"accepted",V{answer.second.accepted}},{"tick",V{answer.second.tick}}}));
   if(!installed){if(actor==original.candidate_actor_id){if(!accepted)actions.push_back(action(x,actor,PoliticalAnswerSuccession{original.id,true},"本人接受未来任职意愿"));actions.push_back(action(x,actor,PoliticalAnswerSuccession{original.id,false},accepted?"本人撤回未来意愿":"本人谢绝提名"));if(accepted&&notice){auto office=read_political_succession_office(common,n.organizations,n.organization_catalog,*p);if(office.ok)actions.push_back(action(x,actor,PoliticalAccedeSuccession{accepted->id,notice->death_fact_id,notice->binding_fact_id,office.value.office_epoch},"凭本人已收文书办理原空职"));}}else{ActingAuthority authority{p->organization_id,p->leader_office_id,original.office_epoch,actor};actions.push_back(action(x,actor,PoliticalWithdrawSuccession{authority,original.id},"原首任明确撤回本提名"));}}
   D row{{"kind",V{"known_nomination"}},{"nomination_fact_id",V{original.id}},{"policy_id",V{p->id}},{"issuer_actor_id",V{original.issuer_actor_id}},{"candidate_actor_id",V{original.candidate_actor_id}},{"response_until",V{original.response_until}},{"known_answers",V{std::move(answers)}},{"actions",V{std::move(actions)}}};if(actor==original.issuer_actor_id)for(const auto& w:n.state.withdrawals.rows())if(w.second.nomination_fact_id==original.id)row.push_back({"own_withdrawal_fact_id",V{w.first}});if(actor==original.candidate_actor_id){row.push_back({"formally_acceded",V{installed}});if(notice)row.push_back({"known_notice_binding_fact_id",V{notice->binding_fact_id}});}return V{std::move(row)};});
 }
 if(cursor>count)return {false,{},common_failure("PoliticalSuccessionCursorInvalid").error};D page{{"ok",V{true}},{"source_identity",identity(common.state().identity)},{"observer_actor_id",V{actor}},{"place_id",V{place}},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(count>cursor+16)page.push_back({"next_cursor",V{cursor+16}});return {true,V{std::move(page)},{}};
}
}
